import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,writeFileSync,readFileSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import {join,resolve,sep} from 'node:path';import {spawnSync} from 'node:child_process';import {savedRehearsalGuideFixtures} from './helpers/workspace-fixtures.js';
test('plain-source CLI create/check/extract preserves exact inputs and emits no source for mismatches',()=>{
 const folder=mkdtempSync(join(tmpdir(),'threecore-source-bundle-')),beforeText=savedRehearsalGuideFixtures()[0].text,afterText=JSON.stringify(JSON.parse(beforeText))+'\r\n',before=join(folder,'before.json'),after=join(folder,'after.json'),bundle=join(folder,'bundle.json'),run=(args,exit=0)=>{const result=spawnSync(process.execPath,['scripts/wallet-saved-bundle.js',...args],{encoding:'utf8',windowsHide:true,timeout:30000});assert.equal(result.error,undefined);assert.equal(result.status,exit,result.stderr);return result;};
 try{writeFileSync(before,beforeText);writeFileSync(after,afterText);const prepared=run(['create',before,after]).stdout;writeFileSync(bundle,prepared);const receipt=JSON.parse(run(['check',bundle,'--json']).stdout);assert.equal(receipt.originalsAvailable,false);assert.equal(receipt.sourceFilesAvailable,true);assert.equal(run(['extract',bundle,'before']).stdout,beforeText);assert.equal(run(['extract',bundle,'after']).stdout,afterText);const wrong=JSON.parse(prepared),comparison=JSON.parse(wrong.comparisonText);comparison.sourceTextComparison.sameText=true;wrong.comparisonText=JSON.stringify(comparison);writeFileSync(bundle,JSON.stringify(wrong));assert.equal(run(['extract',bundle,'after'],2).stdout,'');assert.equal(readFileSync(before,'utf8'),beforeText);assert.equal(readFileSync(after,'utf8'),afterText);}
 finally{assert(resolve(folder).startsWith(resolve(tmpdir())+sep));rmSync(folder,{recursive:true,force:true});}
});
